import React, { useState } from 'react';
import Blobs from '../components/Blobs';
import Orb3D from '../components/Orb3D';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', sub:'Tuff dag',      colors:['#9a2020','#3a0808','#c84040'], blob:'warm' },
  { score:2, emoji:'😟', label:'Dåligt',         sub:'Lite tungt',    colors:['#8a4010','#3a1a04','#b86030'], blob:'warm' },
  { score:3, emoji:'😐', label:'Okej',           sub:'Varken eller',  colors:['#504030','#201810','#706050'], blob:'default' },
  { score:4, emoji:'🙂', label:'Bra',            sub:'Ganska bra',    colors:['#204840','#0c2018','#409070'], blob:'calm' },
  { score:5, emoji:'😄', label:'Väldigt bra',    sub:'Riktigt bra!',  colors:['#203880','#0c1640','#4060c0'], blob:'calm' },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick'); // pick | note | done
  const [saved,    setSaved]      = useState(false);

  const active = hovered ?? selected ?? 2; // default middle
  const mood   = MOODS[active];

  const handlePick = (score) => {
    setSelected(score);
    setTimeout(() => setStep('note'), 300);
  };

  const handleSave = () => {
    const m = MOODS[selected];
    addMood(m.score + 1, m.emoji, m.label, note); // score is index 0-4, we want 1-5
    setStep('done');
  };

  // Actually score is already 1-5 in the score field, fix:
  const handleSaveFixed = () => {
    const m = MOODS.find(m => m.score === selected + 1);
    const picked = MOODS[selected];
    addMood(picked.score, picked.emoji, picked.label, note);
    setStep('done');
  };

  if (todayChecked && !saved) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32 }}>
          <Orb3D size={160} colors={['#304860','#101828','#5080a0']} speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(24px,5vw,36px)', fontWeight:700, letterSpacing:'-0.03em', color:'#fff', marginBottom:12 }}>Redan incheckad idag</h2>
        <p style={{ fontSize:14, color:'rgba(255,255,255,0.4)', marginBottom:36, fontWeight:300 }}>Kom tillbaka imorgon.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#13121a', fontSize:13, fontWeight:600 }}>Se historik</button>
          <button onClick={()=>setPage('home')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'done') return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 32px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32 }}>
          <Orb3D size={180} colors={MOODS[selected].colors} speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:12, lineHeight:1 }}>Sparat</h2>
        <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300 }}>Bra att du checkade in.</p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#13121a', fontSize:13, fontWeight:600 }}>Se historik</button>
          <button onClick={()=>setPage('home')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Hem</button>
        </div>
      </div>
    </div>
  );

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant={MOODS[selected].blob} />
      <div style={{ position:'relative', zIndex:1, padding:'80px 32px 60px', maxWidth:440, width:'100%', animation:'fadeUp .5s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:36 }}>
          <Orb3D size={140} colors={MOODS[selected].colors} speed={0.25} />
        </div>
        <div style={{ display:'flex', align:'center', gap:12, marginBottom:8, justifyContent:'center' }}>
          <span style={{ fontSize:28 }}>{MOODS[selected].emoji}</span>
          <h2 style={{ fontSize:28, fontWeight:700, letterSpacing:'-0.03em', color:'#fff', lineHeight:1.1 }}>{MOODS[selected].label}</h2>
        </div>
        <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', textAlign:'center', marginBottom:36, fontWeight:300 }}>{MOODS[selected].sub}</p>

        <div className="glass" style={{ borderRadius:20, padding:'20px', marginBottom:16 }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.18em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:12 }}>Valfri notering</p>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag? Hur kändes det?"
            style={{ width:'100%', background:'transparent', border:'none', color:'#fff', fontSize:14, fontWeight:300, resize:'none', height:88, outline:'none', lineHeight:1.7 }}
          />
        </div>

        <button onClick={handleSaveFixed}
          style={{ width:'100%', padding:'15px', borderRadius:100, background:'rgba(255,255,255,0.92)', color:'#13121a', fontSize:14, fontWeight:600, marginBottom:12 }}>
          Spara incheckning
        </button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'10px', fontSize:13, color:'rgba(255,255,255,0.3)' }}>← Ändra humör</button>
      </div>
    </div>
  );

  // Step: pick — full screen, large type, orb as bg element
  return (
    <div style={{ minHeight:'100vh', position:'relative', overflow:'hidden' }}>
      <Blobs variant={mood.blob} />

      {/* Giant orb bleeding off screen top-right */}
      <div style={{ position:'absolute', top:'-18%', right:'-18%', zIndex:0, opacity:0.7, pointerEvents:'none', animation:'drift 12s ease-in-out infinite' }}>
        <Orb3D size={480} colors={mood.colors} speed={0.18} morphing={true} />
      </div>

      <div style={{ position:'relative', zIndex:1, minHeight:'100vh', display:'flex', flexDirection:'column', justifyContent:'flex-end', padding:'80px 32px 52px', maxWidth:520, margin:'0 auto' }}>

        {/* Big editorial text top-left */}
        <div style={{ position:'absolute', top:80, left:32, right:32 }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:16 }}>Daglig check-in</p>
          <h1 style={{ fontSize:'clamp(40px,9vw,68px)', fontWeight:700, letterSpacing:'-0.05em', lineHeight:0.88, color:'#fff' }}>
            HUR<br/>
            <span style={{ color:'rgba(255,255,255,0.22)' }}>MÅR DU<br/>IDAG?</span>
          </h1>
        </div>

        {/* Mood options — large, minimal, like a list */}
        <div style={{ display:'flex', flexDirection:'column', gap:4, width:'100%' }}>
          <p style={{ fontFamily:'DM Mono,monospace', fontSize:9, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:12 }}>Välj ett alternativ</p>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isHov = hovered === idx;
            const isSel = selected === idx;
            return (
              <button key={m.score}
                onMouseEnter={() => setHovered(idx)}
                onMouseLeave={() => setHovered(null)}
                onClick={() => handlePick(idx)}
                style={{
                  display:'flex', alignItems:'center', justifyContent:'space-between',
                  padding:'16px 20px',
                  borderRadius:16,
                  background: isHov || isSel ? 'rgba(255,255,255,0.09)' : 'rgba(255,255,255,0.03)',
                  border: `1px solid ${isHov || isSel ? 'rgba(255,255,255,0.16)' : 'rgba(255,255,255,0.06)'}`,
                  transform: isHov ? 'translateX(6px)' : 'none',
                  transition:'all .2s cubic-bezier(0.16,1,0.3,1)',
                  backdropFilter:'blur(20px)',
                }}>
                <div style={{ display:'flex', alignItems:'center', gap:14 }}>
                  <span style={{ fontSize:22, transition:'transform .2s', transform: isHov ? 'scale(1.2)' : 'scale(1)' }}>{m.emoji}</span>
                  <div style={{ textAlign:'left' }}>
                    <div style={{ fontSize:15, fontWeight:600, color: isHov ? '#fff' : 'rgba(255,255,255,0.8)', letterSpacing:'-0.01em' }}>{m.label}</div>
                    <div style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.3)', letterSpacing:'0.08em', marginTop:1 }}>{m.sub}</div>
                  </div>
                </div>
                <span style={{ fontSize:12, color:'rgba(255,255,255,0.25)', opacity: isHov ? 1 : 0, transition:'opacity .2s' }}>→</span>
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}
